parameters.jsCode:
/**
 * Re-attaches the paper metadata to the model's structured output, and is
 * where every value constraint is actually enforced.
 *
 * The JSON schema on the parser deliberately carries types only. Gemini
 * supports a subset of JSON Schema and quietly ignores minItems, maximum,
 * enum and additionalProperties - but the parser still validates against
 * them on the way back, so a strict schema fails a response the model was
 * never told to constrain. Ranges belong in the prompt; enforcement belongs
 * here, where it is deterministic and survives swapping the provider.
 */
const paper = $('Loop Over Papers').item.json;
const analysis = $json.output ?? $json;

const slug = (t) =>
  String(t)
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');

// Tags: slugged, deduped, capped. Across runs the same concept comes back as
// "RAG", "rag " and "Rag", which makes the tag line useless for searching.
const topics = [...new Set((analysis.topics ?? []).map(slug).filter(Boolean))].slice(0, 5);

// Score: a model returns 11, 8.5 or "8/10" often enough to matter, and
// Number("8/10") is NaN - which would quietly score a relevant paper 0 and
// drop it from the digest. Pull the first number out of whatever arrived.
const firstNumber = (v) => {
  if (typeof v === 'number') return v;
  const m = String(v ?? '').match(/-?\d+(?:\.\d+)?/);
  return m ? Number(m[0]) : NaN;
};

const rawScore = firstNumber(analysis.relevance_score);
const score = Number.isFinite(rawScore) ? Math.max(0, Math.min(10, Math.round(rawScore))) : 0;

// Enumerations: snap to the allowed set rather than trusting the model, and
// fall back to the least assertive option instead of failing the paper.
const pick = (value, allowed, fallback) => {
  const v = slug(value);
  return allowed.includes(v) ? v : fallback;
};

const paperType = pick(
  analysis.paper_type,
  ['method', 'benchmark', 'dataset', 'theory', 'survey', 'application', 'position'],
  'method',
);

const priority = pick(
  analysis.reading_priority,
  ['read-now', 'read-this-week', 'skim', 'archive'],
  'skim',
);

// Contributions: an array most of the time, occasionally one newline-joined
// string. Both are cheap to accept.
const rawContributions = analysis.key_contributions;
const contributions = (
  Array.isArray(rawContributions) ? rawContributions : String(rawContributions ?? '').split('\n')
)
  .map((c) => String(c).replace(/^[-*\u2022]\s*/, '').trim())
  .filter(Boolean)
  .slice(0, 4);

const text = (v) => {
  const t = String(v ?? '').trim();
  return t || 'Not stated in the abstract.';
};

return {
  json: {
    ...paper,
    ...analysis,
    topics,
    relevance_score: score,
    relevance_reason: text(analysis.relevance_reason),
    tldr: text(analysis.tldr),
    why_it_matters: text(analysis.why_it_matters),
    method: text(analysis.method),
    results: text(analysis.results),
    limitations: text(analysis.limitations),
    paper_type: paperType,
    reading_priority: priority,
    key_contributions: contributions,
    contributions_text: contributions.map((c) => '- ' + c).join('\n'),
    analysed_at: new Date().toISOString(),
  },
};

/**
 * Builds the Discord embed for one paper.
 *
 * Discord rejects the entire message with a 400 if any single limit is
 * exceeded, and a webhook gives you no useful error body to debug it with, so
 * every cap is enforced here rather than hoped for: title 256, description
 * 4096, field value 1024, 25 fields, and 6000 characters across the whole
 * embed counted together.
 */
const p = $json;

const CAP = { title: 256, description: 4096, field: 1024, fields: 25, total: 6000 };

const cut = (s, n) => {
  const t = String(s ?? '').trim();
  return t.length <= n ? t : t.slice(0, n - 1).trimEnd() + '\u2026';
};

// The stripe colour carries the score before anyone reads the number.
const colour =
  p.relevance_score >= 9 ? 0xd94f4f :
  p.relevance_score >= 8 ? 0xe0913e :
  p.relevance_score >= 7 ? 0x3f7fd9 :
  0x6b7280;

const field = (name, value, inline = false) => {
  const v = String(value ?? '').trim();
  return v ? { name, value: cut(v, CAP.field), inline } : null;
};

const embed = {
  title: cut(p.title, CAP.title),
  url: p.abs_url,
  description: cut(p.tldr + '\n\n_' + p.why_it_matters + '_', CAP.description),
  color: colour,
  timestamp: p.published,
  author: { name: cut(p.authors_line, CAP.title) },
  footer: {
    text: p.arxiv_id + ' ' + p.version + ' \u00b7 ' + p.primary_category + ' \u00b7 scored ' + p.relevance_score + '/10',
  },
  fields: [
    field('Key contributions', p.contributions_text),
    field('Method', p.method),
    field('Results', p.results),
    field('Limitations', p.limitations),
    field('Type', p.paper_type, true),
    field('Priority', p.reading_priority, true),
    field('Categories', (p.categories ?? []).join(', '), true),
    field('Links', '[abstract](' + p.abs_url + ')  \u00b7  [pdf](' + p.pdf_url + ')'),
  ]
    .filter(Boolean)
    .slice(0, CAP.fields),
};

// The 6000 budget is measured across title, description, author, footer and
// every field name and value together - not per field. Halve the longest
// field until it fits rather than dropping fields, which would lose sections.
const weight = (e) =>
  (e.title?.length ?? 0) +
  (e.description?.length ?? 0) +
  (e.author?.name?.length ?? 0) +
  (e.footer?.text?.length ?? 0) +
  e.fields.reduce((sum, f) => sum + f.name.length + f.value.length, 0);

while (weight(embed) > CAP.total) {
  const longest = embed.fields.reduce((a, b) => (a.value.length >= b.value.length ? a : b));
  if (longest.value.length <= 200) break;
  longest.value = cut(longest.value, Math.floor(longest.value.length / 2));
}

// Tags ride in the message content rather than the embed: that is the part
// Discord shows in the channel preview and in notifications.
const content = (p.topics ?? []).map((t) => '\u0060' + t + '\u0060').join(' ');

// allowed_mentions is not optional politeness. A paper whose title or
// abstract contains @everyone would otherwise ping the entire server, and
// arXiv titles are not a trusted input.
const payload = {
  content,
  embeds: [embed],
  allowed_mentions: { parse: [] },
};

return {
  json: {
    ...p,
    discord_content: content,
    embed_json: JSON.stringify(embed),
    embed_weight: weight(embed),
    discord_payload: JSON.stringify(payload),
  },
};

/**
 * The Discord node's response replaces the item, so the paper has to be put
 * back before it returns to the loop and, from there, into the digest.
 *
 * Batch size is 1, so .first() is exact rather than a heuristic - this node
 * stops being correct the moment someone raises that batch size.
 */
const paper = $('Merge Analysis').first().json;

// The webhook was called with ?wait=true, so Discord returned the message it
// created instead of an empty 204. Those two ids are the only way to find the
// card again later and read its reactions - there is no endpoint that lists a
// webhook's own messages.
const posted = $input.first()?.json ?? {};

return [
  {
    json: {
      ...paper,
      posted_to_discord: true,
      discord_message_id: posted.id ?? null,
      discord_channel_id: posted.channel_id ?? null,
    },
  },
];

/**
 * Packs the run's results for the store.
 *
 * Fed from the loop's "done" output, so it carries every paper the run
 * touched — the ones that were posted and the ones that scored too low. Both
 * matter: the store's whole purpose is to answer "was the cheap ranker right?",
 * and that question needs the rejects as much as the keepers.
 *
 * This branch is optional. Leave `store_url` empty in Config and the HTTP node
 * downstream fails, continues on error, and the digest goes out regardless.
 */
const cfg = $('Config').first().json;

const papers = $input
  .all()
  .map((i) => i.json)
  // Papers whose analysis failed arrive as n8n error objects with no id.
  .filter((p) => p && p.arxiv_id);

return [
  {
    json: {
      store_endpoint: String(cfg.store_url ?? '').replace(/\/+$/, '') + '/papers',
      ranker_token: cfg.ranker_token ?? '',
      count: papers.length,
      payload: JSON.stringify({ papers }),
    },
  },
];

/**
 * Renders the Telegram message.
 *
 * Fed straight from the loop's "done" output, which carries every paper the
 * run touched — kept and skipped alike. Selecting, ranking and capping all
 * happen here rather than in a Filter → Sort → Limit chain, for one reason:
 * on a day when nothing clears the threshold there must still be *something*
 * to render, because n8n does not execute a node with zero input items and
 * the digest would silently never be sent. A Filter cannot express that, and
 * a Filter with alwaysOutputData emits an empty item that the Sort node then
 * rejects with "Couldn't find the field 'relevance_score'". Doing it in code
 * removes the whole class of problem: an empty list is just an empty list.
 *
 * Telegram rejects any message over 4096 characters, so the digest is emitted
 * as one item per chunk and packed on paper boundaries — an entry is never cut
 * in half, which would also break the HTML tags around it.
 */
const CHUNK_LIMIT = 3500;

const cfg = $('Config').first().json;
const screened = $('Unseen Papers Only').all().length;
const threshold = Number(cfg.relevance_threshold);

// Papers whose analysis failed arrive as n8n error objects with no arxiv_id
// and no score. The upstream branch cannot filter them on a score they do not
// have, so they are dropped here.
const papers = $input
  .all()
  .map((i) => i.json)
  .filter((p) => p && p.arxiv_id && Number.isFinite(Number(p.relevance_score)))
  .filter((p) => Number(p.relevance_score) >= threshold)
  .sort((a, b) => Number(b.relevance_score) - Number(a.relevance_score))
  .slice(0, Number(cfg.digest_size));

// Telegram's HTML parse mode is strict: one unescaped "<" in a paper title
// returns a 400 and the whole digest is lost.
const esc = (s) =>
  String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Fields are clipped before the entry is assembled, never after: truncating
// the finished string would cut an HTML tag in half. The caps only bite when
// a model ignores the "max 30 words" instruction, but a run-on tldr must not
// be able to push a single entry past what the chunker can place.
const clip = (s, n) => {
  const t = String(s ?? '').trim();
  return t.length <= n ? t : t.slice(0, n - 1).trimEnd() + '…';
};

// Provenance, surfaced rather than logged. When the ranking service is
// unreachable the run still produces a perfectly plausible digest - of the
// newest papers instead of the best ones - and nothing in the message would
// say so. The first time this degraded it went unnoticed for a week, which
// is the whole argument for putting one line in front of the reader.
const degraded = $input.all().some((i) => i.json?.ranked_by === 'recency');

const header = [
  '<b>' + $now.toFormat('cccc d LLL') + ' - AI Paper Digest</b>',
  '<i>' + papers.length + ' of ' + screened + ' new papers scored ' + threshold + '+ - full cards in Discord</i>',
  degraded ? '<i>\u26a0 ranked by recency - the ranking service did not answer</i>' : '',
]
  .filter(Boolean)
  .join('\n');

if (papers.length === 0) {
  return [{ json: { text: header + '\n\nNothing cleared the bar today.', chunk: 1, chunks: 1 } }];
}

const entries = papers.map((p, i) => {
  const tags = (p.topics ?? []).map((t) => '#' + t.replace(/-/g, '_')).join(' ');
  const links = [
    '<a href="' + p.abs_url + '">abs</a>',
    '<a href="' + p.pdf_url + '">pdf</a>',
  ];

  return [
    '<b>' + (i + 1) + '. ' + esc(clip(p.title, 180)) + '</b>  <code>' + p.relevance_score + '/10</code>',
    esc(clip(p.tldr, 240)),
    '<i>' + esc(clip(p.why_it_matters, 340)) + '</i>',
    (tags ? tags + '\n' : '') + links.join(' - ') + '  <code>' + esc(p.arxiv_id) + '</code>',
  ].join('\n');
});

const chunks = [];
let current = header;
for (const entry of entries) {
  if (current.length + entry.length + 2 > CHUNK_LIMIT) {
    chunks.push(current);
    current = entry;
  } else {
    current += '\n\n' + entry;
  }
}
chunks.push(current);

return chunks.map((text, i) => ({
  json: {
    text: chunks.length > 1 ? text + '\n\n<i>part ' + (i + 1) + '/' + chunks.length + '</i>' : text,
    chunk: i + 1,
    chunks: chunks.length,
  },
}));
